// Determina o mês atual em português
const meses = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const hoje  = new Date();
const mesAtual  = meses[hoje.getMonth()];
const diaAtual  = String(hoje.getDate()).padStart(2,'0');
const mesNum    = String(hoje.getMonth()+1).padStart(2,'0');
const anoAtual  = hoje.getFullYear();
const dataHoje  = `${diaAtual}/${mesNum}/${anoAtual}`;
const diasMes   = new Date(anoAtual, hoje.getMonth()+1, 0).getDate();
const diasRestantes = diasMes - hoje.getDate();

return [{ json: { mesAtual, dataHoje, diaAtual: parseInt(diaAtual), diasMes, diasRestantes, anoAtual } }];

const lancamentos = $('Ler Lançamentos do Mês').all().map(i=>i.json);
const orcamentos  = $('Ler Orçamentos').all().map(i=>i.json);
const memorias    = $('Ler Memória do Agente').all().map(i=>i.json);
const ctx         = $('Obter Data Atual').first().json;
const { mesAtual, dataHoje, diaAtual, diasMes, diasRestantes } = ctx;

// Limites de orçamento
const limites = {};
orcamentos.forEach(o => {
  const cat = o['Categoria']||'';
  const lim = parseFloat(o['Limite Mensal (R$)']||0);
  if (cat) limites[cat] = lim;
});

// Gastos por categoria
const gastos = {};
const gastos_hoje = {};
lancamentos.forEach(l => {
  const tipo = l['Tipo']||'';
  const cat  = l['Categoria']||'Outros';
  const val  = parseFloat(l['Valor (R$)']||0);
  const data = l['Data']||'';
  if (tipo === 'Despesa') {
    gastos[cat] = (gastos[cat]||0) + val;
    if (data === dataHoje) gastos_hoje[cat] = (gastos_hoje[cat]||0) + val;
  }
});

const total_despesas = Object.values(gastos).reduce((s,v)=>s+v,0);
const total_hoje     = Object.values(gastos_hoje).reduce((s,v)=>s+v,0);
const total_receitas = lancamentos.filter(l=>l['Tipo']==='Receita').reduce((s,l)=>s+parseFloat(l['Valor (R$)']||0),0);

// Projeção para fim do mês
const media_diaria   = diaAtual > 0 ? total_despesas / diaAtual : 0;
const projecao_mes   = media_diaria * diasMes;
const total_orcamento = Object.values(limites).reduce((s,v)=>s+v,0);

// Status por categoria
const status_cats = Object.entries(gastos).map(([cat, gasto]) => {
  const lim = limites[cat] || 0;
  const pct = lim > 0 ? gasto/lim : null;
  return { cat, gasto, lim, pct };
}).sort((a,b)=>b.gasto-a.gasto);

// Memória recente
const mem_texto = memorias.slice(-10).map(m=>`[${m['Data']||''}] ${m['Observação']||m['observacao']||''}`).join('\n') || 'Nenhum histórico anterior.';

// Montar contexto para Claude
const contexto = `Você é um assistente financeiro pessoal inteligente e amigável. Analise os dados abaixo e elabore um relatório diário para ser enviado via WhatsApp.

## DATA DE HOJE
${dataHoje} – ${mesAtual} (dia ${diaAtual} de ${diasMes}, faltam ${diasRestantes} dias)

## GASTOS DE HOJE (${dataHoje})
Total: R$ ${total_hoje.toFixed(2).replace('.',',')}
${Object.entries(gastos_hoje).map(([c,v])=>`  - ${c}: R$ ${v.toFixed(2).replace('.',',')}`).join('\n') || '  Nenhum gasto registrado hoje.'}

## RESUMO DO MÊS ATÉ AGORA
Total despesas: R$ ${total_despesas.toFixed(2).replace('.',',')}
Total receitas: R$ ${total_receitas.toFixed(2).replace('.',',')}
Saldo: R$ ${(total_receitas-total_despesas).toFixed(2).replace('.',',')}

## GASTOS POR CATEGORIA vs ORÇAMENTO
${status_cats.map(s=>{
  const pct_str = s.pct !== null ? ` (${(s.pct*100).toFixed(0)}% do limite R$ ${s.lim.toFixed(2).replace('.',',')})` : ' (sem limite definido)';
  return `  - ${s.cat}: R$ ${s.gasto.toFixed(2).replace('.',',')}${pct_str}`;
}).join('\n')}

## PROJEÇÃO
Média diária de gastos: R$ ${media_diaria.toFixed(2).replace('.',',')}
Projeção para fim do mês: R$ ${projecao_mes.toFixed(2).replace('.',',')}
Orçamento total mensal: R$ ${total_orcamento.toFixed(2).replace('.',',')}
${projecao_mes > total_orcamento ? '⚠️ PROJEÇÃO ACIMA DO ORÇAMENTO TOTAL' : '✅ Projeção dentro do orçamento'}

## MEMÓRIA / HISTÓRICO DE OBSERVAÇÕES
${mem_texto}

---

Sua resposta deve ser uma mensagem de WhatsApp (use *negrito* e emojis). Inclua:
1. Saudação e data
2. Resumo do dia (gastos de hoje)
3. Como está o mês em relação ao orçamento (use metáforas simples)
4. Uma ou duas categorias que merecem atenção
5. Projeção para fim do mês
6. Um conselho financeiro personalizado baseado nos dados
7. Uma frase motivacional curta

Seja direto, amigável e use emojis. Máximo 350 palavras.`;

return [{ json: { model: 'claude-opus-4-6', max_tokens: 1500, messages: [{ role: 'user', content: contexto }], _ctx: { mesAtual, dataHoje, total_hoje, total_despesas, total_receitas, media_diaria, projecao_mes, status_cats } } }];

const msg_claude = $input.first().json.content?.[0]?.text || 'Erro ao gerar análise.';
const ctx = $('Montar Contexto para Agente').first().json._ctx;
return [{ json: { mensagem: msg_claude, ...ctx } }];
